<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { analyzeImport, commitImport } from '../../api/imports.ts';
import type { ImportMerchantDecision, StagedImportBatch, StagedMerchant, StagedTransaction } from '../../api/contracts.ts';
import { formatDate, formatInteger, formatMoney } from '../../shared/format.ts';
import { canContinue, importSteps, initialDecision, needsReconciliation, previewRows, rankedIdentities, type DuplicateAction } from './model.ts';

const emit = defineEmits<{ imported: [] }>();
const openState = ref(false); const step = ref(0); const batch = ref<StagedImportBatch | null>(null); const busy = ref(false); const error = ref(''); const notice = ref('');
const decisions = ref(new Map<string, ImportMerchantDecision>()); const duplicates = ref(new Map<string, DuplicateAction>()); const reconciled = ref(new Set<string>()); const dragActive = ref(false);
const fileInput = ref<HTMLInputElement | null>(null);
const reviewMerchants = computed(() => batch.value?.merchants.filter((item) => item.needs_review) ?? []);
const knownMerchants = computed(() => (batch.value?.merchants.length ?? 0) - reviewMerchants.value.length);
const insertRows = computed(() => batch.value ? previewRows(batch.value, decisions.value, duplicates.value) : []);
const nextEnabled = computed(() => !busy.value && canContinue(step.value, batch.value, decisions.value, duplicates.value, reconciled.value));
const totals = computed(() => (batch.value?.files ?? []).reduce((sum, file) => ({ parsed: sum.parsed + (file.parsed ?? 0), newRows: sum.newRows + (file.new_rows ?? 0), exact: sum.exact + (file.exact_duplicates ?? 0), possible: sum.possible + (file.possible_duplicates ?? 0), pending: sum.pending + (file.pending_rows ?? 0), plans: sum.plans + (file.installment_plans ?? 0) }), { parsed: 0, newRows: 0, exact: 0, possible: 0, pending: 0, plans: 0 }));

function open(): void { openState.value = true; error.value = ''; notice.value = ''; }
function close(): void { if (!busy.value) openState.value = false; }
function browse(): void { fileInput.value?.click(); }
async function analyze(files: File[]): Promise<void> {
  if (!files.length) return; busy.value = true; error.value = ''; notice.value = '';
  try { const result = await analyzeImport(files); batch.value = result; step.value = 1; duplicates.value = new Map(); reconciled.value = new Set(); decisions.value = new Map(result.merchants.filter((item) => item.needs_review).map((merchant) => [merchant.merchant_normalized, initialDecision(merchant, result.display_identities)])); notice.value = `${result.files.length} files staged. Nothing was added to the database.`; }
  catch (caught) { error.value = caught instanceof Error ? caught.message : 'Could not analyze files'; }
  finally { busy.value = false; if (fileInput.value) fileInput.value.value = ''; }
}
function chooseFiles(event: Event): void { void analyze([...(event.target as HTMLInputElement).files ?? []]); }
function drop(event: DragEvent): void { dragActive.value = false; void analyze([...(event.dataTransfer?.files ?? [])]); }
function setDuplicate(id: string, value: string): void { const next = new Map(duplicates.value); if (value) next.set(id, value as DuplicateAction); else next.delete(id); duplicates.value = next; }
function setReconciled(filename: string, checked: boolean): void { const next = new Set(reconciled.value); if (checked) next.add(filename); else next.delete(filename); reconciled.value = next; }
function updateDecision(key: string, field: keyof ImportMerchantDecision, value: string): void {
  const current = decisions.value.get(key); if (!current) return; const next = { ...current, [field]: value, suggested_match: false } as ImportMerchantDecision;
  if (field === 'resolution') { if (value === 'needs_review') { next.category = 'Needs review'; next.scope = 'batch'; } if (value === 'provider') { const merchant = batch.value?.merchants.find((item) => item.merchant_normalized === key); next.category = merchant?.provider_category || 'Needs review'; next.scope = 'exact'; } if (value === 'link') next.scope = 'exact'; }
  const map = new Map(decisions.value); map.set(key, next); decisions.value = map;
}
function chooseIdentity(key: string, groupId: string): void { const identity = batch.value?.display_identities.find((item) => item.canonical_group_id === groupId); if (!identity) return; updateDecision(key, 'display_name', identity.display_name); updateDecision(key, 'canonical_group_id', identity.canonical_group_id); updateDecision(key, 'resolution', 'link'); if (identity.category_status === 'unanimous') updateDecision(key, 'category', identity.category!); }
function identityChoices(merchant: StagedMerchant) { return rankedIdentities(merchant.merchant_raw, batch.value?.display_identities ?? []).slice(0, 12); }
function identityFor(row: StagedTransaction): { display: string; category: string } { const decision = decisions.value.get(row.merchant_normalized); const merchant = batch.value?.merchants.find((item) => item.merchant_normalized === row.merchant_normalized); return { display: decision?.display_name || merchant?.display_name || row.merchant, category: decision?.category || merchant?.category || 'Needs review' }; }
function statusFor(row: StagedTransaction): string { if (row.reviewed_new) return 'Reviewed as new'; if (row.source_status === 'pending') return 'Pending · not final'; if (row.source_status === 'outside_cycle') return 'Outside billing cycle'; if (row.installment_number) return `Installment ${row.installment_number}/${row.installment_total ?? '?'}`; return 'Confirmed new'; }
function safeDate(value: string | null | undefined): string { return value ? formatDate(value) : '—'; }
function next(): void { if (step.value < 4 && nextEnabled.value) step.value += 1; else if (step.value === 4 && nextEnabled.value) void commit(); }
async function commit(): Promise<void> {
  if (!batch.value) return; busy.value = true; error.value = '';
  try { const result = await commitImport({ batch_id: batch.value.batch_id, decisions: [...decisions.value.values()], duplicate_decisions: [...duplicates.value].map(([candidate_id, action]) => ({ candidate_id, action })), reconciled_files: [...reconciled.value] }); const inserted = result.results.reduce((sum, item) => sum + (item.inserted ?? 0), 0); batch.value = null; decisions.value = new Map(); duplicates.value = new Map(); reconciled.value = new Set(); step.value = 0; openState.value = false; emit('imported'); notice.value = `${inserted} transactions imported after a database backup.`; }
  catch (caught) { error.value = caught instanceof Error ? caught.message : 'Import failed'; }
  finally { busy.value = false; }
}
function handleKeydown(event: KeyboardEvent): void { if (event.key === 'Escape' && openState.value) close(); }
onMounted(() => document.addEventListener('keydown', handleKeydown)); onBeforeUnmount(() => document.removeEventListener('keydown', handleKeydown)); defineExpose({ open });
</script>

<template><Teleport to="body"><div v-if="openState" class="import-manager-backdrop" @mousedown.self="close"><section class="import-manager" role="dialog" aria-modal="true" aria-labelledby="import-manager-title"><button type="button" class="transactions-modal-close" aria-label="Close import" @click="close">×</button>
  <header class="import-manager-head"><div><p>Data management</p><h2 id="import-manager-title">Import statements</h2><span>Analyze, review and reconcile before anything is written.</span></div><span v-if="batch" class="import-staged-badge">Staged · not saved</span></header>
  <nav class="import-steps" aria-label="Import steps"><button v-for="(name,index) in importSteps" :key="name" type="button" :class="{ active: step===index, done:index<step }" :disabled="(!batch&&index>0)||index>step" @click="step=index"><b>{{ index<step?'✓':index+1 }}</b><span>{{ name }}</span></button></nav>
  <div class="import-manager-content" :aria-busy="busy"><p v-if="busy" class="import-busy">{{ step===4?'Creating backup and importing…':'Analyzing files without changing your database…' }}</p><p v-if="error" class="transaction-editor-error" role="alert">{{ error }}</p><p v-if="notice" class="import-notice" role="status">{{ notice }}</p>
    <section v-if="!busy&&step===0" class="import-files-step"><div v-if="batch" class="import-callout">A staged batch with <strong>{{ batch.files.length }} files</strong> is ready. Choose new files to replace it or continue.</div><button type="button" class="import-drop" :class="{ dragging:dragActive }" @click="browse" @dragover.prevent="dragActive=true" @dragleave.prevent="dragActive=false" @drop.prevent="drop"><strong>Drop statements here or click to browse</strong><span>XLSX and PDF · multiple files supported · analysis is read-only</span></button><input ref="fileInput" type="file" multiple accept=".xlsx,.pdf" hidden @change="chooseFiles"></section>
    <section v-else-if="!busy&&step===1&&batch"><div class="import-metrics"><div><span>Parsed rows</span><strong>{{ totals.parsed }}</strong></div><div><span>Confirmed new</span><strong>{{ totals.newRows }}</strong></div><div><span>Exact duplicates</span><strong>{{ totals.exact }}</strong></div><div><span>Needs review</span><strong>{{ totals.possible }}</strong></div><div><span>Pending</span><strong>{{ totals.pending }}</strong></div><div><span>Installment plans</span><strong>{{ totals.plans }}</strong></div></div>
      <div v-for="warning in batch.coverage_warnings" :key="`${warning.filename}-${warning.message}`" class="import-callout warning"><strong>••{{ warning.card_last4 }} · {{ warning.filename }}</strong> — {{ warning.message }}</div>
      <div class="import-table-wrap"><table><thead><tr><th>File</th><th>Source</th><th>Coverage</th><th>Rows</th><th>Status</th></tr></thead><tbody><tr v-for="file in batch.files" :key="file.filename"><td><strong>{{ file.filename }}</strong><small>{{ file.format }}</small></td><td>{{ (file.provider||file.kind).toUpperCase() }}<small>{{ file.card_last4?`•• ${file.card_last4}`:'—' }}</small></td><td>{{ file.statement_range||'—' }}</td><td>{{ file.new_rows||0 }} new<small>{{ file.exact_duplicates||0 }} exact · {{ file.possible_duplicates||0 }} review · {{ file.pending_rows||0 }} pending</small></td><td><i>{{ file.status.replaceAll('_',' ') }}</i></td></tr></tbody></table></div>
      <div class="import-duplicate-section"><h3>Exact duplicates <b>{{ batch.exact_duplicates.length }} automatically excluded</b></h3><div v-for="row in batch.exact_duplicates" :key="`${row.filename}-${row.transaction_key}`" class="import-duplicate-row"><span><strong>{{ row.merchant||'Income' }}</strong><small>{{ row.filename }} · {{ safeDate(row.transaction_date) }}</small></span><strong>{{ formatMoney(row.amount||0) }}</strong><span>Excluded automatically<small>{{ row.reason||'Exact identity already exists' }}</small></span></div><p v-if="!batch.exact_duplicates.length">No exact duplicates found.</p></div>
      <div class="import-duplicate-section"><h3>Possible duplicates <b>{{ batch.possible_duplicates.length }} decisions required</b></h3><div v-for="row in batch.possible_duplicates" :key="row.candidate_id" class="import-duplicate-row"><span><strong>{{ row.merchant }}</strong><small>{{ safeDate(row.transaction_date) }} · {{ row.filename }}</small></span><strong>{{ formatMoney(row.amount||0) }}</strong><label><span>{{ row.reason }}</span><select :value="duplicates.get(row.candidate_id||'')||''" @change="setDuplicate(row.candidate_id||'',($event.target as HTMLSelectElement).value)"><option value="">Choose action…</option><option value="skip">Treat as duplicate</option><option value="import">Import as new</option></select></label></div><p v-if="!batch.possible_duplicates.length">No uncertain matches need review.</p></div>
    </section>
    <section v-else-if="!busy&&step===2&&batch"><div class="import-callout"><strong>{{ knownMerchants }} merchants matched existing rules.</strong> Review {{ reviewMerchants.length }} unfamiliar merchants. “Needs review” safely imports without a permanent rule.</div><div v-if="reviewMerchants.length" class="import-table-wrap merchant-decisions"><table><thead><tr><th>Merchant</th><th>Resolution</th><th>Category</th><th>Display name</th><th>Apply to</th></tr></thead><tbody><tr v-for="merchant in reviewMerchants" :key="merchant.merchant_normalized"><td><strong>{{ merchant.merchant_raw }}</strong><small>{{ merchant.transactions }} transactions · {{ formatMoney(merchant.amount) }}</small></td><td><select :value="decisions.get(merchant.merchant_normalized)?.resolution" @change="updateDecision(merchant.merchant_normalized,'resolution',($event.target as HTMLSelectElement).value)"><option value="create">Create new rule</option><option value="link">Link existing merchant</option><option v-if="merchant.provider_category" value="provider">Use provider value</option><option value="needs_review">Needs review</option><option value="exclude">Exclude rows</option></select></td><td><select :value="decisions.get(merchant.merchant_normalized)?.category" :disabled="decisions.get(merchant.merchant_normalized)?.resolution==='exclude'" @change="updateDecision(merchant.merchant_normalized,'category',($event.target as HTMLSelectElement).value)"><option v-for="category in [...new Set([...batch.categories,'Needs review'])]" :key="category">{{ category }}</option></select></td><td><input :value="decisions.get(merchant.merchant_normalized)?.display_name" :disabled="decisions.get(merchant.merchant_normalized)?.resolution==='exclude'" list="display-identities" @input="updateDecision(merchant.merchant_normalized,'display_name',($event.target as HTMLInputElement).value)"><select class="identity-link-select" :value="decisions.get(merchant.merchant_normalized)?.canonical_group_id||''" @change="chooseIdentity(merchant.merchant_normalized,($event.target as HTMLSelectElement).value)"><option value="">Existing display name…</option><option v-for="identity in identityChoices(merchant)" :key="identity.canonical_group_id" :value="identity.canonical_group_id">{{ identity.display_name }} · {{ identity.category_status==='unanimous'?identity.category:'Mixed categories' }}</option></select></td><td><select :value="decisions.get(merchant.merchant_normalized)?.scope" :disabled="['link','exclude'].includes(decisions.get(merchant.merchant_normalized)?.resolution||'')" @change="updateDecision(merchant.merchant_normalized,'scope',($event.target as HTMLSelectElement).value)"><option value="exact">This name, future too</option><option value="batch">This batch only</option></select></td></tr></tbody></table></div><div v-else class="import-empty">All merchants matched approved database rules.</div></section>
    <section v-else-if="!busy&&step===3&&batch"><div class="import-callout warning"><strong>Reconciliation uses the scheduled statement charge.</strong> Pending and outside-cycle transactions stay separate.</div><div class="import-table-wrap"><table><thead><tr><th>File</th><th>Parsed total</th><th>Official total</th><th>Difference</th><th>Confirmation</th></tr></thead><tbody><tr v-for="file in batch.files" :key="file.filename"><td><strong>{{ file.filename }}</strong><small>{{ (file.provider||file.kind).toUpperCase() }}</small></td><td>{{ formatMoney(file.reconciliation?.parsed_total||0) }}</td><td>{{ file.reconciliation?.official_total==null?'Check original':formatMoney(file.reconciliation.official_total) }}</td><td>{{ file.reconciliation?.difference==null?'—':formatMoney(file.reconciliation.difference) }}</td><td><label v-if="needsReconciliation(file)" class="reconcile-check"><input type="checkbox" :checked="reconciled.has(file.filename)" @change="setReconciled(file.filename,($event.target as HTMLInputElement).checked)"> I reviewed {{ file.reconciliation?.status==='mismatch'?'the mismatch':'the total' }}</label><i v-else>{{ file.reconciliation?.status==='matched'?'Matched':'No check needed' }}</i></td></tr></tbody></table></div></section>
    <section v-else-if="!busy&&step===4&&batch"><div class="import-approve"><div><h3>Safety checks complete</h3><ul><li>Files parsed before import</li><li>Every possible duplicate reviewed</li><li>Existing merchant rules kept first priority</li><li>Required statement totals confirmed</li><li>A complete database backup will be created before writing</li></ul></div><div><h3>Ready to import</h3><p><span>Files</span><strong>{{ batch.files.length }}</strong></p><p><span>New transaction rows</span><strong>{{ insertRows.length }}</strong></p><p><span>Duplicates skipped</span><strong>{{ batch.exact_duplicates.length+[...duplicates.values()].filter(v=>v==='skip').length }}</strong></p></div></div><div class="import-preview"><h3>Transactions to be inserted <b>{{ insertRows.length }} rows</b></h3><div class="import-table-wrap"><table><thead><tr><th>Date</th><th>Merchant</th><th>Category</th><th>Amount</th><th>Card</th><th>Status</th></tr></thead><tbody><tr v-for="row in insertRows" :key="`${row.filename}-${row.transaction_key}-${row.candidate_id}`"><td>{{ safeDate(row.billing_date||row.transaction_date) }}<small v-if="row.billing_date&&row.transaction_date!==row.billing_date">Purchased {{ safeDate(row.transaction_date) }}</small></td><td><strong>{{ identityFor(row).display }}</strong><small>{{ row.merchant }}</small></td><td>{{ identityFor(row).category }}</td><td>{{ formatMoney(row.amount??row.original_amount??0) }}</td><td>{{ row.card_last4?`•• ${row.card_last4}`:'—' }}</td><td><i>{{ statusFor(row) }}</i></td></tr></tbody></table></div></div></section>
  </div><footer class="import-manager-footer"><span>{{ ['Select files to analyze.','Exact duplicates are excluded; review uncertain matches.','Resolve unfamiliar merchants or leave them for later.','Compare parsed totals with original statements.','Approve only after reviewing every inserted row.'][step] }}</span><div><button type="button" :disabled="busy||step===0" @click="step-=1">Back</button><button type="button" class="primary" :disabled="!nextEnabled" @click="next">{{ step===4?'Approve & import':'Continue' }}</button></div></footer>
</section></div></Teleport></template>
